CREATE VIEW datamart.v_ventas_analisis AS
 SELECT v.venta_id,
    v.origen_datos,
    ((v.origen_datos || ':'::text) || (v.orden_id)::text) AS compra_clave,
    v.orden_id,
    v.fecha,
    f.anio,
    f.mes,
    f.nombre_mes,
    f.trimestre,
    f.dia_semana,
    f.nombre_dia,
    v.hora,
    v.sucursal_id,
    s.nombre_sucursal,
    v.platillo_id,
    p.nombre_platillo,
    p.categoria,
    v.cliente_id,
    c.etiqueta AS cliente,
    c.identificado AS cliente_identificado,
    v.cantidad,
    v.precio_unitario,
    v.importe
   FROM ((((datamart.fact_ventas v
     JOIN datamart.dim_fecha f ON ((f.fecha = v.fecha)))
     JOIN datamart.dim_sucursal s ON ((s.sucursal_id = v.sucursal_id)))
     JOIN datamart.dim_platillo p ON ((p.platillo_id = v.platillo_id)))
     JOIN datamart.dim_cliente c ON ((c.cliente_id = v.cliente_id)));


