--
-- Name: v_demanda_horaria; Type: VIEW; Schema: datamart; Owner: -
--

CREATE VIEW datamart.v_demanda_horaria AS
 SELECT origen_datos,
    dia_semana,
    nombre_dia,
    hora,
    sum(importe) AS ventas,
    sum(cantidad) AS unidades,
    count(DISTINCT compra_clave) AS compras,
    count(DISTINCT fecha) AS dias_observados,
    round(((count(DISTINCT compra_clave))::numeric / (NULLIF(count(DISTINCT fecha), 0))::numeric), 2) AS compras_por_dia_observado
   FROM datamart.v_ventas_analisis
  GROUP BY origen_datos, dia_semana, nombre_dia, hora;


--
-- Name: v_kpis_origen; Type: VIEW; Schema: datamart; Owner: -
--

CREATE VIEW datamart.v_kpis_origen AS
 SELECT origen_datos,
    count(*) AS lineas,
    count(DISTINCT compra_clave) AS compras,
    sum(cantidad) AS unidades,
    sum(importe) AS ventas,
    round((sum(importe) / (NULLIF(count(DISTINCT compra_clave), 0))::numeric), 2) AS ticket_promedio,
    min(fecha) AS primera_fecha,
    max(fecha) AS ultima_fecha
   FROM datamart.v_ventas_analisis
  GROUP BY origen_datos;


--
-- Name: v_ranking_platillos; Type: VIEW; Schema: datamart; Owner: -
--

CREATE VIEW datamart.v_ranking_platillos AS
 SELECT origen_datos,
    platillo_id,
    nombre_platillo,
    categoria,
    sum(importe) AS ventas,
    sum(cantidad) AS unidades,
    dense_rank() OVER (PARTITION BY origen_datos ORDER BY (sum(importe)) DESC) AS posicion
   FROM datamart.v_ventas_analisis
  GROUP BY origen_datos, platillo_id, nombre_platillo, categoria;


